searchDatas1[15] = ['','Starten des Tools zum Festlegen der IP-Adresse','./startup_ipaddress.html', '	Starten des Tools zum Festlegen der IP-Adresse	Dieser Abschnitt erläutert, wie Sie das Tool zum Festlegen der IP-Adresse. starten. 	Startvorgang	Für Windows 10/Windows Server 2016/Windows Server 2019/Windows Server 2022	Wählen Sie das [Start]-Menü 	→ [fi Series] 	→ [Tool zum Festlegen der IP-Adresse for fi Series].	Für Windows 11/Windows Server 2025	Wählen Sie das [Start]-Menü 	→ [Alle Apps] 	→ [fi Series] 	→ [Tool zum Festlegen der IP-Adresse for fi Series].	TIPP	Sie können das Tool zum Festlegen der IP-Adresse auch starten, indem Sie auf die Schaltfläche [IP-Adresse festlegen] im Fenster [Scanner-Auswahltool] klicken.'];
